script:
(function () {
  'use strict';

  var btnStart = document.getElementById('btnStartSweep');
  var btnPause = document.getElementById('btnPauseSweep');
  var btnStop = document.getElementById('btnStopSweep');
  var freqReadout = document.getElementById('freqReadout');
  var progressFill = document.getElementById('sweepProgressFill');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var toolError = document.getElementById('toolError');
  var durationSlider = document.getElementById('durationSlider');
  var durationValue = document.getElementById('durationValue');
  var durationInput = document.getElementById('durationInput');
  var volumeSlider = document.getElementById('volumeSlider');
  var volumeValue = document.getElementById('volumeValue');
  var manualFreqSlider = document.getElementById('manualFreqSlider');
  var manualFreqValue = document.getElementById('manualFreqValue');
  var startFreqInput = document.getElementById('startFreqInput');
  var stopFreqInput = document.getElementById('stopFreqInput');
  var sweepType = document.getElementById('sweepType');
  var waveformSelect = document.getElementById('waveformSelect');
  var startLevelInput = document.getElementById('startLevelInput');
  var endLevelInput = document.getElementById('endLevelInput');
  var continueTone = document.getElementById('continueTone');
  var statOctaves = document.getElementById('statOctaves');
  var statPerOctave = document.getElementById('statPerOctave');
  var statHalfway = document.getElementById('statHalfway');
  var statRate = document.getElementById('statRate');
  var statVolume = document.getElementById('statVolume');

  var MAX_GAIN = 0.3; // conservative ceiling -- see this site's safety notes for playback tools; a sweep can be uncomfortable/damaging at full volume
  var MIN_FREQ = 20, MAX_FREQ = 20000; // manual slider range
  var INPUT_MIN = 1, INPUT_MAX = 22000;
  // Square and sawtooth carry more energy than a sine at the same peak level.
  var WAVE_LEVEL = { sine: 1, triangle: 1, square: 0.55, sawtooth: 0.7 };

  var Ctor = window.AudioContext || window.webkitAudioContext;
  var audioCtx = null;
  var oscillator = null;
  var levelGain = null; // start/end volume automation
  var gainNode = null;  // on/off envelope
  var master = null;    // Volume slider
  var tickIntervalId = null;
  var sweeping = false;
  var paused = false;
  var holding = false; // steady tone (manual, or after the sweep) playing
  var plan = null;     // settings frozen at sweep start
  var elapsed = 0;     // seconds of sweep progress
  var segStartCtx = 0, segStartElapsed = 0;

  function showError(msg) {
    if (!toolError) return;
    toolError.textContent = msg;
    toolError.classList.add('show');
  }
  function clearError() {
    if (!toolError) return;
    toolError.textContent = '';
    toolError.classList.remove('show');
  }

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function formatFreq(hz) {
    return hz >= 1000 ? (hz / 1000).toFixed(2) + ' kHz' : (hz < 100 ? hz.toFixed(1) : Math.round(hz)) + ' Hz';
  }
  function formatSecs(s) {
    return (s >= 100 ? s.toFixed(0) : (s >= 1 ? s.toFixed(1) : s.toFixed(2))) + ' s';
  }

  function nyquistLimit() {
    return audioCtx ? Math.floor(audioCtx.sampleRate / 2) - 1 : INPUT_MAX;
  }
  function clampFreq(f, fallback) {
    if (!isFinite(f) || f <= 0) f = fallback;
    return Math.max(INPUT_MIN, Math.min(Math.min(INPUT_MAX, nyquistLimit()), f));
  }
  function currentDuration() {
    var d = parseFloat(durationInput.value);
    if (!isFinite(d) || d <= 0) d = parseFloat(durationSlider.value) || 15;
    return Math.max(0.1, Math.min(600, d));
  }
  function clampLevel(v) {
    v = parseFloat(v);
    if (!isFinite(v)) v = 100;
    return Math.max(1, Math.min(100, v));
  }

  function readSettings() {
    var f0 = clampFreq(parseFloat(startFreqInput.value), 20);
    var f1 = clampFreq(parseFloat(stopFreqInput.value), 20000);
    if (f0 === f1) f1 = f0 * 2 <= INPUT_MAX ? f0 * 2 : f0 / 2;
    return {
      f0: f0, f1: f1, T: currentDuration(), type: sweepType.value,
      v0: clampLevel(startLevelInput.value), v1: clampLevel(endLevelInput.value)
    };
  }

  // Exponential by default -- a linear sweep from 20-20000 Hz spends almost
  // its entire duration above 10 kHz and blows through the whole
  // musically/audibly relevant range in the first fraction of a second,
  // per this tool's own spec note. Linear stays available for analyzers
  // that expect it.
  function freqAt(p, t) {
    var frac = Math.max(0, Math.min(1, t / p.T));
    if (p.type === 'linear') return p.f0 + (p.f1 - p.f0) * frac;
    return p.f0 * Math.pow(p.f1 / p.f0, frac);
  }
  function levelAt(p, t) {
    var frac = Math.max(0, Math.min(1, t / p.T));
    return (p.v0 + (p.v1 - p.v0) * frac) / 100;
  }

  // ---------- Graph ----------
  function ensureContext() {
    if (!Ctor) {
      showError('Your browser doesn’t support the Web Audio API, so the sweep can’t play here.');
      return Promise.reject(new Error('no-webaudio'));
    }
    if (!audioCtx) {
      try {
        audioCtx = new Ctor();
      } catch (e) {
        showError('The browser refused to start audio output: ' + (e && e.message ? e.message : e));
        return Promise.reject(e);
      }
      oscillator = audioCtx.createOscillator();
      levelGain = audioCtx.createGain();
      gainNode = audioCtx.createGain();
      master = audioCtx.createGain();
      oscillator.type = waveformSelect.value;
      oscillator.frequency.value = MIN_FREQ;
      gainNode.gain.value = 0;
      master.gain.value = currentGainTarget();
      oscillator.connect(levelGain);
      levelGain.connect(gainNode);
      gainNode.connect(master);
      master.connect(audioCtx.destination);
      oscillator.start();
    }
    return audioCtx.resume().then(function () { return audioCtx; }, function () { return audioCtx; });
  }

  function withContext(fn) {
    ensureContext().then(function () {
      clearError();
      fn();
    }).catch(function (e) {
      if (e && e.message === 'no-webaudio') return;
      showError('Audio could not start: ' + (e && e.message ? e.message : e));
    });
  }

  function currentGainTarget() {
    return (parseFloat(volumeSlider.value) / 100) * MAX_GAIN;
  }

  function rampParam(param, target, secs) {
    var now = audioCtx.currentTime;
    param.cancelScheduledValues(now);
    param.setValueAtTime(param.value, now);
    param.linearRampToValueAtTime(target, now + (secs || 0.05));
  }
  function rampGainTo(target) {
    if (!gainNode || !audioCtx) return;
    rampParam(gainNode.gain, target);
  }
  function envLevel() {
    return WAVE_LEVEL[waveformSelect.value] || 1;
  }

  // ---------- Calculated outputs ----------
  function updateStats() {
    var p = readSettings();
    var oct = Math.abs(Math.log(p.f1 / p.f0) / Math.LN2);
    statOctaves.textContent = oct.toFixed(2) + ' octaves';
    if (p.type === 'linear') {
      var hzps = Math.abs(p.f1 - p.f0) / p.T;
      var lo = Math.min(p.f0, p.f1), hi = Math.max(p.f0, p.f1);
      // A linear sweep spends lo/rate seconds on its lowest octave and
      // (hi/2)/rate on its highest.
      statPerOctave.textContent = oct >= 1 ? formatSecs(lo / hzps) + ' → ' + formatSecs((hi / 2) / hzps) : formatSecs(p.T);
      statRate.textContent = (hzps >= 1000 ? (hzps / 1000).toFixed(2) + ' kHz' : hzps.toFixed(1) + ' Hz') + ' per s';
    } else {
      statPerOctave.textContent = oct ? formatSecs(p.T / oct) : '—';
      statRate.textContent = (oct / p.T).toFixed(2) + ' octaves per s';
    }
    statHalfway.textContent = formatFreq(freqAt(p, p.T / 2));
    statVolume.textContent = p.v0 === p.v1 ? 'Constant (' + p.v0 + ')' : (p.v1 > p.v0 ? 'Rises ' : 'Falls ') + p.v0 + ' → ' + p.v1;
  }

  // ---------- Sweep control ----------
  function currentElapsed() {
    if (!sweeping || paused || !audioCtx) return elapsed;
    return segStartElapsed + (audioCtx.currentTime - segStartCtx);
  }

  // Schedules frequency + start/end volume automation on the audio clock
  // from `from` seconds into the sweep (also used to resume after pause).
  function beginSegment(from) {
    var now = audioCtx.currentTime;
    var remaining = Math.max(0.001, plan.T - from);
    var fp = oscillator.frequency;
    fp.cancelScheduledValues(now);
    fp.setValueAtTime(freqAt(plan, from), now);
    if (plan.type === 'linear') fp.linearRampToValueAtTime(plan.f1, now + remaining);
    else fp.exponentialRampToValueAtTime(plan.f1, now + remaining);
    var lp = levelGain.gain;
    lp.cancelScheduledValues(now);
    lp.setValueAtTime(levelAt(plan, from), now);
    lp.linearRampToValueAtTime(plan.v1 / 100, now + remaining);
    segStartCtx = now;
    segStartElapsed = from;
  }

  // Timer-driven, not requestAnimationFrame -- the oscillator itself follows
  // automation scheduled on the audio clock; this only updates the readout
  // and ends the run, and rAF is fully suspended whenever the tab isn't
  // visible.
  function tick() {
    if (!sweeping || paused || !audioCtx) return;
    var t = currentElapsed();
    if (t >= plan.T) { finishSweep(); return; }
    elapsed = t;
    freqReadout.textContent = formatFreq(freqAt(plan, t));
    progressFill.style.width = Math.round((t / plan.T) * 100) + '%';
  }

  function holdFrequency(f) {
    var now = audioCtx.currentTime;
    oscillator.frequency.cancelScheduledValues(now);
    oscillator.frequency.setValueAtTime(f, now);
  }

  function finishSweep() {
    sweeping = false;
    paused = false;
    stopTickLoop();
    freqReadout.textContent = formatFreq(plan.f1);
    progressFill.style.width = '100%';
    btnStart.textContent = 'Start Sweep';
    btnPause.disabled = true;
    if (continueTone.checked) {
      holding = true;
      holdFrequency(plan.f1);
      btnStop.disabled = false;
      setDiagnostic('ok', '<strong>Sweep finished — still playing ' + formatFreq(plan.f1) + '.</strong> Click Stop when done.');
      return;
    }
    rampGainTo(0);
    btnStop.disabled = true;
    setDiagnostic('ok', '<strong>Sweep finished.</strong> Note the frequency shown if you heard a dropout, rattle or resonance, and use the manual slider to zero in on it.');
  }

  function startTickLoop() {
    if (tickIntervalId) clearInterval(tickIntervalId);
    tickIntervalId = setInterval(tick, 30);
  }
  function stopTickLoop() {
    if (tickIntervalId) { clearInterval(tickIntervalId); tickIntervalId = null; }
  }

  function startSweep() {
    withContext(function () {
      plan = readSettings();
      oscillator.type = waveformSelect.value;
      elapsed = 0;
      sweeping = true;
      paused = false;
      holding = false;
      beginSegment(0);
      rampGainTo(envLevel());
      btnStart.textContent = 'Restart Sweep';
      btnPause.disabled = false;
      btnPause.textContent = 'Pause';
      btnStop.disabled = false;
      setDiagnostic('ok', '<strong>Sweeping ' + formatFreq(plan.f0) + ' → ' + formatFreq(plan.f1) + '…</strong> Listen for any point where the tone drops out, rattles, or seems to resonate unusually loud.');
      startTickLoop();
      tick();
    });
  }

  function togglePause() {
    if (!sweeping || !audioCtx) return;
    if (!paused) {
      elapsed = currentElapsed();
      paused = true;
      holdFrequency(freqAt(plan, elapsed));
      levelGain.gain.cancelScheduledValues(audioCtx.currentTime);
      levelGain.gain.setValueAtTime(levelAt(plan, elapsed), audioCtx.currentTime);
      rampGainTo(0);
      stopTickLoop();
      btnPause.textContent = 'Resume';
    } else {
      paused = false;
      beginSegment(elapsed);
      rampGainTo(envLevel());
      startTickLoop();
      btnPause.textContent = 'Pause';
    }
  }

  function stopSweep() {
    sweeping = false;
    paused = false;
    holding = false;
    stopTickLoop();
    rampGainTo(0);
    progressFill.style.width = '0%';
    freqReadout.textContent = '—';
    elapsed = 0;
    btnStart.textContent = 'Start Sweep';
    btnPause.disabled = true;
    btnPause.textContent = 'Pause';
    btnStop.disabled = true;
    setDiagnostic('', 'Stopped.');
  }

  function manualFreq() {
    var pct = parseFloat(manualFreqSlider.value) / 1000;
    return MIN_FREQ * Math.pow(MAX_FREQ / MIN_FREQ, pct);
  }

  function playManualFrequency() {
    withContext(function () {
      sweeping = false;
      paused = false;
      holding = true;
      stopTickLoop();
      btnPause.disabled = true;
      btnPause.textContent = 'Pause';
      btnStart.textContent = 'Start Sweep';
      btnStop.disabled = false;
      oscillator.type = waveformSelect.value;
      var freq = Math.min(manualFreq(), nyquistLimit());
      var now = audioCtx.currentTime;
      oscillator.frequency.cancelScheduledValues(now);
      oscillator.frequency.setValueAtTime(freq, now);
      levelGain.gain.cancelScheduledValues(now);
      levelGain.gain.setValueAtTime(1, now);
      manualFreqValue.textContent = formatFreq(freq);
      freqReadout.textContent = formatFreq(freq);
      rampGainTo(envLevel());
      setDiagnostic('ok', '<strong>Playing ' + formatFreq(freq) + ' steadily.</strong> Click Stop when done.');
    });
  }

  btnStart.addEventListener('click', startSweep);
  btnPause.addEventListener('click', togglePause);
  btnStop.addEventListener('click', stopSweep);

  [startFreqInput, stopFreqInput, startLevelInput, endLevelInput].forEach(function (el) {
    el.addEventListener('input', updateStats);
  });
  sweepType.addEventListener('change', updateStats);

  durationSlider.addEventListener('input', function () {
    durationValue.textContent = durationSlider.value + ' s';
    durationInput.value = durationSlider.value;
    updateStats();
  });
  durationInput.addEventListener('input', function () {
    var d = currentDuration();
    durationValue.textContent = (d % 1 ? d.toFixed(1) : d) + ' s';
    durationSlider.value = Math.max(1, Math.min(120, Math.round(d)));
    updateStats();
  });

  waveformSelect.addEventListener('change', function () {
    if (oscillator) oscillator.type = waveformSelect.value;
    if (audioCtx && (holding || (sweeping && !paused))) rampGainTo(envLevel());
  });

  volumeSlider.addEventListener('input', function () {
    volumeValue.textContent = volumeSlider.value + '%';
    if (master && audioCtx) rampParam(master.gain, currentGainTarget());
  });
  manualFreqSlider.addEventListener('input', function () {
    manualFreqValue.textContent = formatFreq(manualFreq());
  });
  manualFreqSlider.addEventListener('change', playManualFrequency);
  manualFreqSlider.dispatchEvent(new Event('input'));

  window.addEventListener('pagehide', function () {
    sweeping = false;
    paused = false;
    holding = false;
    stopTickLoop();
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
    oscillator = levelGain = gainNode = master = null;
  });
  document.addEventListener('visibilitychange', function () {
    // Silence (rather than let it keep sweeping unheard) when the tab is
    // hidden -- a diagnostic tone playing on unattended, especially at the
    // high-frequency end, isn't something to leave running invisibly.
    if (document.visibilityState === 'hidden' && audioCtx) {
      if (sweeping || holding) stopSweep();
      if (audioCtx.state === 'running') audioCtx.suspend().catch(function () {});
    }
  });

  updateStats();

  if (!Ctor) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    btnStart.disabled = true;
  }
})();
